# Housing simulator, Sources (Math) pane. English comes from hmath_en.json (the page's own innerHTML, taken in a browser),
# so the keys match exactly. In translations, [n]text[/] becomes the n-th <a ...> of the English, with its href kept.
import json, os, re
_EN = json.load(open(os.path.join(os.path.dirname(__file__), 'hmath_en.json')))
T, H = {}, {}

def _fill(en, tr):
    tags = re.findall(r'<a [^>]*>', en)
    return re.sub(r'\[(\d+)\](.*?)\[/\]', lambda m: tags[int(m.group(1)) - 1] + m.group(2) + '</a>', tr)

def X(i, es, zh, pl):
    x = _EN[i]
    if '<' in x['h']:
        H[x['h']] = tuple(_fill(x['h'], t) for t in (es, zh, pl))
    else:
        T[x['t']] = (es, zh, pl)

